import{_ as i,l as o,o as a,c as m,v as t,p as d,x as l,d as n,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"解码的算术强度","description":"","frontmatter":{"title":"解码的算术强度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/arithmetic-intensity-decode.md","filePath":"llm/arithmetic-intensity-decode.md","lastUpdated":1789023840000}'),c={name:"llm/arithmetic-intensity-decode.md"};function p(_,e,B,E,A,f){const r=o("Mermaid");return a(),m("div",null,[e[1]||(e[1]=t('<h1 id="解码的算术强度" tabindex="-1">解码的算术强度 <a class="header-anchor" href="#解码的算术强度" aria-label="Permalink to &quot;解码的算术强度&quot;">​</a></h1><div class="epigraph"><p>算术强度是 FLOPs 除以字节；decode 每步搬完全部权重，只换一行激活，强度掉到带宽屋顶之下。</p><footer>—— Williams et al., Roofline: An Insightful Visual Performance Model, CACM 2009；接到 Transformer 推理见 Pope et al., 2022</footer></div><p><a href="/llm/kv-cache-size-math">上一课</a>写出 KV 有多少字节。本课问这些字节在一步 decode 里能摊到多少计算。Williams 的屋顶线把工作点分成算力屋顶与带宽屋顶；<a href="/llm/decode-memory-wall">显存墙</a>已经给出逐步时间下界。这里把 <em>算术强度</em> \\(I=\\mathrm{FLOPs}/\\mathrm{bytes}\\) 钉成可比较的量：prefill 高、\\(B=1\\) 的 decode 低、加大 batch 或投机加宽查询则回升。后课用拐点谈「batch 要到多大才离开带宽屋顶」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一步 decode 的主导 FLOPs 是投影与 FFN 的「瘦」GEMM（激活行数 \\(\\approx B\\)）加上对长度为 \\(n\\) 的 KV 做注意力。主导字节是读权重 \\(W_{\\mathrm{bytes}}\\) 加读 \\(\\mathrm{KV}(n)\\)。<a href="/llm/flashattention">FlashAttention</a> 避免写 \\(n\\times n\\)，不把二次矩阵算进 HBM 流量，计算仍是 \\(\\Theta(n d)\\) 量级的点积。当 \\(B\\) 小，\\(W_{\\mathrm{bytes}}\\) 几乎不被复用，\\(I\\) 远低于 GPU 的屋顶比 \\(\\mathrm{peakFLOP}/B_{\\mathrm{HBM}}\\)，墙钟由搬运决定。缺口是把这句话写成强度，而不是再描述一遍「GPU 利用率低」。</p><p>投机校验把 \\(n_q\\) 从 1 拉到 \\(\\gamma+1\\)，同一份权重摊到略多的查询，强度上升——这是投机在带宽墙上能赢的硬件原因，不只是「少了逐步次数」。</p><p><span class="marginnote">强度随 \\(n\\) 缓升（注意力项），但权重项是常数。长上下文并不会自动变成 compute-bound：权重那一项仍然在。只有 \\(B\\) 或 \\(n_q\\) 把权重摊薄，工作点才移动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估一步：</p> \\[I_{\\mathrm{decode}}\\approx\\frac{\\mathrm{FLOPs}(B,n)}{W_{\\mathrm{bytes}}+\\mathrm{KV}(n)\\cdot B_{\\mathrm{eff}}}. \\]<p>\\(B_{\\mathrm{eff}}\\) 是本步真正要扫 KV 的序列数（连续批里各 \\(n\\) 不同，用和）。与硬件屋顶比 \\(I_{\\star}=\\mathrm{peak}/\\mathrm{bandwidth}\\) 比较：\\(I\\lt I_{\\star}\\) 则带宽绑定。优化按分子分母：减字节（量化、GQA、MLA）、增 FLOPs 复用（加大 \\(B\\)、chunked prefill 混入、投机加宽 \\(n_q\\)）。换一张 FLOPS 翻倍、带宽不变的卡，带宽绑定区的 TPOT 几乎不动——用强度可以事先预言，而不必上机「试一下」。</p>',11)),(a(),d(h,null,{default:l(()=>[s(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E4%B8%80%E6%AD%A5%20FLOPs%22%5D%20--%3E%20I%5B%22I%20%3D%20FLOPs%20%2F%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20BY%5B%22%E6%9D%83%E9%87%8D%20%2B%20KV%20%E5%AD%97%E8%8A%82%22%5D%20--%3E%20I%0A%20%20I%20--%3E%20CMP%7B%22I%20%E4%B8%8E%E5%B1%8B%E9%A1%B6%E6%AF%94%22%7D%0A%20%20CMP%20--%3E%7C%22%E4%BD%8E%E4%BA%8E%22%7C%20BW%5B%22%E5%B8%A6%E5%AE%BD%E7%BB%91%E5%AE%9A%22%5D%0A%20%20CMP%20--%3E%7C%22%E9%AB%98%E4%BA%8E%22%7C%20C%5B%22%E7%AE%97%E5%8A%9B%E7%BB%91%E5%AE%9A%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>屋顶线是不等式，不是平均利用率仪表。仪表上的 SM% 低，可能是真的带宽绑定，也可能是核启动太碎、或 <a href="/llm/kv-layout">KV 布局</a>跨步导致有效带宽远低于峰值。强度分析应配合 profiler 的 HBM 吞吐：若 HBM 已接近峰值而 SM% 低，解释成立；若 HBM 也低，先修布局与占用率（FlashDecoding 切 KV）。Pope 等人强调阶段拆分：同一模型，prefill 与 decode 的 \\(I\\) 可以差一个数量级，服务若用一个并行度套两段，必有一段坐错屋顶。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用训练的 MFU 估 decode。不要把 FA 的「少写 A」写成「decode 变成 compute-bound」。MoE 只激活部分专家时，\\(W_{\\mathrm{bytes}}\\) 是 <em>被点到的</em> 专家加注意力权重，强度画像随路由波动——均值会骗人。后课把 \\(I(B)\\) 画成拐点。</p><p>出处：Williams et al., CACM 2009；Pope et al., 2022。不发明编号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>算术强度 \\(I=\\mathrm{FLOPs}/\\mathrm{bytes}\\)；小 batch decode 通常低于屋顶比。</li><li>权重项使长 \\(n\\) 也不能单独把 decode 变成算力绑定。</li><li>加大 \\(B\\)、加宽 \\(n_q\\)、减字节，是移动工作点的合法手段。</li><li>FA 改 HBM 上的 \\(A\\)，不自动改 decode 的屋顶。</li><li>布局与占用率会让有效带宽低于峰值，强度分析要对照 profiler。</li><li>下一课：batch 多大才越过拐点。</li><li>出处：Williams et al., 2009；Pope et al., 2022。</li></ul>',7))])}const b=i(c,[["render",p]]);export{u as __pageData,b as default};
